function [np, cr] = st_pair_count(cr, nc, fov)
%ST_PAIR_COUNT  How many pairs of the first nc catalogue stars lie closer than the field's diagonal (2 sqrt 2 times the half-angle fov):
%   the onboard pair table's length.
%   vectors: 6
%   cr: inout real[1][3][N_STARS] (passed a plain number)
%   nc: int (passed a whole number)
%   fov: real[1] (passed a plain number)
%   returns np: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    np = 0;
    cd = cos(((2 * asils.pc.sqrt_(2)) * fov));
    np = 0;
    for j = (0):((nc) - 1)
        for i = (0):((j) - 1)
            if (asils.pc.dot_((cr((i) + 1, :)).', (cr((j) + 1, :)).') > cd)
                np = (np + 1);
            end
        end
    end
end
